package vn.smartfarm.iot.control;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import org.springframework.web.server.ResponseStatusException;
import vn.smartfarm.iot.irrigation.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=true","smartfarm.control.pump-fencing-enabled=true","smartfarm.control.circuit-route-required=true","smartfarm.irrigation.circuit-demo-enabled=true","smartfarm.irrigation.session-enabled=true","smartfarm.irrigation.session-closure-enabled=true","smartfarm.irrigation.session-closure-poll-ms=3600000"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class SessionClosureTest {
 @Autowired PumpService pump;@Autowired PumpCommandFencing fencing;@Autowired PumpCircuitProof proof;@Autowired CircuitValveControl valves;@Autowired IrrigationCircuits circuits;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;
 @MockitoBean CommandTransport transport;@MockitoBean CircuitValveTransport valveTransport;
 UUID boot=UUID.fromString("88000000-0000-4000-8000-000000000001"),vboot=UUID.fromString("88000000-0000-4000-8000-000000000002");PumpCircuitRoute route;
 @BeforeEach void setup()throws Exception{cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");reset(transport,valveTransport);when(transport.controlConnected()).thenReturn(true);when(valveTransport.circuitValveConnected(anyString())).thenReturn(true);
  for(int i=1;i<=2;i++){jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES(?,?,'AREA001','SOIL',2)","PRSOIL"+i,"Soil");for(int j=1;j<=3;j++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES(?,?,'SOIL_MOISTURE','%')","PRSOIL"+i,"SOIL"+j);jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES(?,?,'AREA001',?,'SIMULATOR',30,35)","PRZONE"+i,"Zone","PRSOIL"+i);}
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('PRWATER','Water','AREA001','WATER',2)");jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('PRWATER','LOW','WATER_PRESENT','boolean'),('PRWATER','FLOW','FLOW_RATE','L/min')");
  for(int i=1;i<=2;i++)jdbc.update("INSERT INTO irrigation_circuit(circuit_id,name,zone_id,zone_revision,controller_id,valve_id,pump_id,water_node_id,low_channel_id,flow_channel_id,expected_source) VALUES(?,?,?,1,?,?,'PUMP01','PRWATER','LOW','FLOW','SIMULATOR')","PR"+i,"Circuit","PRZONE"+i,"IRRIGATION"+(77+i),"VALVE"+(77+i));
  route=PumpCircuitRoute.from(circuits.find("PR1"));reportPump(1,0,"OFF",route);reportValve("PR1",1,0,"CLOSED");reportValve("PR2",1,0,"CLOSED");
 }
 @AfterEach void after(){cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");}
 void cleanup(){jdbc.update("DELETE FROM irrigation_session_closure WHERE session_id IN(SELECT session_id FROM irrigation_session WHERE circuit_id IN ('PR1','PR2'))");jdbc.update("DELETE FROM irrigation_session_action WHERE session_id IN(SELECT session_id FROM irrigation_session WHERE circuit_id IN ('PR1','PR2'))");jdbc.update("DELETE FROM irrigation_session WHERE circuit_id IN ('PR1','PR2')");for(String t:List.of("circuit_demo_command","circuit_demo_status","circuit_demo_boot","circuit_demo_gate"))jdbc.update("DELETE FROM "+t+" WHERE valve_id IN ('VALVE78','VALVE79')");jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id IN ('PR1','PR2')");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id IN ('PRZONE1','PRZONE2')");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('PRSOIL1','PRSOIL2','PRWATER')");}
 ObjectNode pumpPacket(long sequence,long ordinal,String state,PumpCircuitRoute r){var p=mapper.createObjectNode().put("schemaVersion",1).put("deviceId","PUMP01").put("bootId",boot.toString()).put("sequence",sequence).put("timestamp",Instant.now().toString()).put("connection","ONLINE").put("reportedState",state).put("safetyLockout",false).put("stateReason",state.equals("ON")?"COMMAND_ON":"COMMAND_OFF");p.putObject("commandFence").put("version",1).put("lastOrdinal",ordinal).put("restartRequired",false);var f=p.putObject("valveInterlock").put("version",1).put("enabled",true).put("dataSource","SIMULATOR").put("state","OPEN").putNull("fault");if(r!=null)f.set("route",mapper.valueToTree(r));return p;}
 void reportPump(long sequence,long ordinal,String state,PumpCircuitRoute r)throws Exception{pump.receive("smartfarm/FARM001/PUMP01/status",mapper.writeValueAsBytes(pumpPacket(sequence,ordinal,state,r)));}
 ObjectNode valvePacket(String id,long seq,long ordinal,String state){var c=circuits.find(id);var p=mapper.createObjectNode().put("schemaVersion",1).put("controlProfile",CircuitValveControl.PROFILE).put("controllerId",c.controllerId()).put("actuatorId",c.valveId()).put("circuitId",id).put("circuitRevision",c.revision()).put("zoneId",c.zoneId()).put("zoneRevision",c.zoneRevision()).put("bootId",vboot.toString()).put("sequence",seq).put("timestamp",Instant.now().toString()).put("dataSource","SIMULATOR").put("feedbackState",state).put("gpioState",state).put("reason",state.equals("OPEN")?"COMMAND_OPEN":"COMMAND_CLOSE").put("demoEnabled",true).put("lastOrdinal",ordinal);p.putObject("positionFeedback").put("version",1).put("enabled",true).put("state",state).putNull("fault");return p;}
 void valveReceive(String id,ObjectNode p)throws Exception{valves.receive(CircuitValveControl.topic(circuits.find(id).valveId(),p.has("commandId")?"ack":"status"),mapper.writeValueAsBytes(p),false);}
 void reportValve(String id,long seq,long ordinal,String state)throws Exception{valveReceive(id,valvePacket(id,seq,ordinal,state));}
 CircuitValveControl.Request vrequest(String id,String action){var c=circuits.find(id);return new CircuitValveControl.Request(UUID.randomUUID(),action,action.equals("OPEN")?30:null,vboot,c.revision(),c.zoneRevision(),Instant.now());}
 CircuitValveControl.Command openValve()throws Exception{var c=valves.create("PR1",vrequest("PR1","OPEN"));var p=valvePacket("PR1",2,c.ordinal(),"OPEN").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","OPEN").put("result","EXECUTED").putNull("errorCode");valveReceive("PR1",p);reportValve("PR1",3,c.ordinal(),"OPEN");return c;}
 PumpCommandFencing.HttpIntent request(String action,Integer seconds,PumpCircuitRoute r){var v=fencing.view().intent();return new PumpCommandFencing.HttpIntent(UUID.randomUUID(),action,seconds,action.equals("OFF")?null:boot,v.revision(),v.asOf(),r);}
 PumpCommandFencing.Receipt start() {return fencing.createHttp(request("ON",5,route),()->{});}
 long ordinal(UUID id){return jdbc.queryForObject("SELECT fence_ordinal FROM pump_command WHERE command_id=?",Long.class,id);}

 @Autowired IrrigationSession service;@Autowired SessionClosure closure;@Autowired org.springframework.transaction.PlatformTransactionManager manager;
 IrrigationSession.Run begin(){var v=service.snapshot("PR1");return service.start("PR1",new IrrigationSession.Start(UUID.randomUUID(),1,1,boot,vboot,5,v.asOf()));}
 IrrigationSession.Action stepRequest(IrrigationSession.Run r,String action){return new IrrigationSession.Action(UUID.randomUUID(),action,r.revision(),service.snapshot("PR1").asOf());}
 IrrigationSession.Receipt step(IrrigationSession.Run r,String action){return service.act("PR1",r.sessionId(),stepRequest(r,action));}
 void opened(IrrigationSession.Run r)throws Exception{var c=valves.lookup("PR1",r.openId());valveReceive("PR1",valvePacket("PR1",2,c.ordinal(),"OPEN").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","OPEN").put("result","EXECUTED").putNull("errorCode"));reportValve("PR1",3,c.ordinal(),"OPEN");reportPump(2,0,"OFF",route);}
 void acknowledgedOff(IrrigationSession.Run r)throws Exception{jdbc.update("UPDATE pump_command SET ack_boot_id=?,ack_sequence=4 WHERE command_id=?",boot,r.offId());jdbc.update("UPDATE pump_command SET state='EXECUTED',reported_state='OFF' WHERE command_id=?",r.offId());if(r.onId()!=null)jdbc.update("UPDATE pump_command SET state='EXECUTED',reported_state='ON',ack_boot_id=?,ack_sequence=3 WHERE command_id=?",boot,r.onId());reportPump(5,ordinal(r.offId()),"OFF",route);}
 void closed(IrrigationSession.Run r)throws Exception{var c=valves.lookup("PR1",r.closeId());valveReceive("PR1",valvePacket("PR1",6,c.ordinal(),"CLOSED").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","CLOSE").put("result","EXECUTED").putNull("errorCode"));reportValve("PR1",7,c.ordinal(),"CLOSED");}
 IrrigationSession.Run waiting(){return step(begin(),"OFF").session();}
 SessionClosure.Arm armRequest(IrrigationSession.Run r){return new SessionClosure.Arm(UUID.randomUUID(),r.revision(),r.offId(),Instant.now());}
 SessionClosure.Record armed(IrrigationSession.Run r){return closure.arm("PR1",r.sessionId(),armRequest(r));}
 SessionClosure.Record saved(UUID id){return closure.snapshot("PR1",id).closure();}
 IrrigationSession.Run current(UUID id){return service.find("PR1",id);}
 void expire(UUID id){jdbc.update("UPDATE irrigation_session_closure SET armed_at=CURRENT_TIMESTAMP-INTERVAL '16 seconds',deadline=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE session_id=?",id);}
 @Test void defaultProfileAndBeforeOffCannotArm(){var r=begin();assertFalse(closure.snapshot("PR1",r.sessionId()).canArm());assertThrows(Exception.class,()->armed(r));var stopped=step(r,"OFF").session();var disabled=new SessionClosure(jdbc,mapper,service,manager,false);assertFalse(disabled.snapshot("PR1",r.sessionId()).canArm());assertThrows(Exception.class,()->disabled.arm("PR1",r.sessionId(),armRequest(stopped)));}
 @Test void armingIsDurableAndDoesNotSendAnyStep()throws Exception{var r=waiting();clearInvocations(transport,valveTransport);var a=armed(r);assertEquals("ARMED",a.state());assertEquals(Duration.ofSeconds(15),Duration.between(a.armedAt(),a.deadline()));closure.poll();assertEquals("ARMED",saved(r.sessionId()).state());verify(transport,never()).publishCommand(any());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void sameArmIsIdempotentAndDifferentDefinitionRejected(){var r=waiting();var body=armRequest(r);var a=closure.arm("PR1",r.sessionId(),body);assertEquals(a,closure.arm("PR1",r.sessionId(),body));assertThrows(Exception.class,()->armed(r));assertThrows(Exception.class,()->closure.arm("PR2",r.sessionId(),body));}
 @Test void staleReviewRevisionOrOffIdentityCannotArm(){var r=waiting();assertThrows(Exception.class,()->closure.arm("PR1",r.sessionId(),new SessionClosure.Arm(UUID.randomUUID(),r.revision()-1,r.offId(),Instant.now())));assertThrows(Exception.class,()->closure.arm("PR1",r.sessionId(),new SessionClosure.Arm(UUID.randomUUID(),r.revision(),UUID.randomUUID(),Instant.now())));assertThrows(Exception.class,()->closure.arm("PR1",r.sessionId(),new SessionClosure.Arm(UUID.randomUUID(),r.revision(),r.offId(),Instant.now().minusSeconds(11))));}
 @Test void onlyConfirmedOffThenClosedCompletesAndNeverStartsNext()throws Exception{var r=waiting();var a=armed(r);acknowledgedOff(r);clearInvocations(transport,valveTransport);closure.poll();assertEquals("WAIT_CLOSED",saved(r.sessionId()).state());var closing=current(r.sessionId());assertEquals(a.closeId(),closing.closeId());assertEquals("WAIT_CLOSED",closing.phase());closure.poll();assertEquals("WAIT_CLOSED",saved(r.sessionId()).state());closed(closing);closure.poll();assertEquals("COMPLETE",saved(r.sessionId()).state());assertEquals("CLOSED_CONFIRMED",current(r.sessionId()).phase());closure.poll();verify(transport,never()).publishCommand(any());verify(valveTransport,times(1)).publishCircuitValve(anyString(),any());assertEquals(List.of("OFF"),jdbc.queryForList("SELECT action FROM pump_command",String.class));assertEquals(List.of("OFF","CLOSE","FINISH"),jdbc.queryForList("SELECT action FROM irrigation_session_action ORDER BY history_id",String.class));}
 @Test void offAckAloneDoesNotCloseWithoutNewStatus()throws Exception{var r=waiting();armed(r);jdbc.update("UPDATE pump_command SET state='EXECUTED',reported_state='OFF',ack_boot_id=?,ack_sequence=4 WHERE command_id=?",boot,r.offId());clearInvocations(valveTransport);closure.poll();assertEquals("ARMED",saved(r.sessionId()).state());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void offStatusWithoutCorrectBootAckDoesNotClose()throws Exception{var r=waiting();armed(r);acknowledgedOff(r);jdbc.update("UPDATE pump_command SET ack_boot_id=? WHERE command_id=?",UUID.randomUUID(),r.offId());clearInvocations(valveTransport);closure.poll();assertEquals("ARMED",saved(r.sessionId()).state());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void closedAckAloneDoesNotFinish()throws Exception{var r=waiting();armed(r);acknowledgedOff(r);closure.poll();var closing=current(r.sessionId());var c=valves.lookup("PR1",closing.closeId());valveReceive("PR1",valvePacket("PR1",6,c.ordinal(),"CLOSED").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","CLOSE").put("result","EXECUTED").putNull("errorCode"));closure.poll();assertEquals("WAIT_CLOSED",current(r.sessionId()).phase());assertEquals("WAIT_CLOSED",saved(r.sessionId()).state());}
 @Test void manualPausePreventsNextStepAndCannotBeRearmed()throws Exception{var r=waiting();var a=armed(r);closure.pause("PR1",r.sessionId(),a.armId());acknowledgedOff(r);clearInvocations(valveTransport);closure.poll();assertEquals("PAUSED",saved(r.sessionId()).state());assertThrows(Exception.class,()->armed(r));verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void newManualOffPausesAutoClosure()throws Exception{var r=waiting();armed(r);var newer=step(r,"OFF").session();assertEquals("PAUSED",saved(r.sessionId()).state());acknowledgedOff(newer);clearInvocations(valveTransport);closure.poll();verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void duplicateOldOffDoesNotCancelArm(){var r=begin();var input=stepRequest(r,"OFF");r=service.act("PR1",r.sessionId(),input).session();armed(r);service.act("PR1",r.sessionId(),input);assertEquals("ARMED",saved(r.sessionId()).state());}
 @Test void externalOffAndRestartInterruptWithoutReplay()throws Exception{var r=waiting();armed(r);fencing.createHttp(request("OFF",null,null),()->{});clearInvocations(transport,valveTransport);closure.poll();assertEquals("INTERRUPTED",saved(r.sessionId()).state());service.interruptOnStartup();closure.poll();verify(transport,never()).publishCommand(any());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void restartDuringArmRequiresRecovery(){var r=waiting();armed(r);service.interruptOnStartup();closure.poll();assertEquals("INTERRUPTED",saved(r.sessionId()).state());assertEquals("RECOVERY_REQUIRED",current(r.sessionId()).phase());}
 @Test void expiryBeforeCloseStopsTheAutomation()throws Exception{var r=waiting();armed(r);expire(r.sessionId());clearInvocations(valveTransport);closure.poll();assertEquals("EXPIRED",saved(r.sessionId()).state());assertEquals("RECOVERY_REQUIRED",current(r.sessionId()).phase());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void uncertainCloseNeverRetriesOrFinishes()throws Exception{var r=waiting();armed(r);acknowledgedOff(r);doThrow(new IllegalStateException()).when(valveTransport).publishCircuitValve(anyString(),any());clearInvocations(valveTransport);closure.poll();closure.poll();closure.poll();assertEquals("UNRESOLVED",saved(r.sessionId()).state());assertEquals("RECOVERY_REQUIRED",current(r.sessionId()).phase());verify(valveTransport,times(1)).publishCircuitValve(anyString(),any());}
 @Test void missingTransportDoesNotReplayCloseWhenRestored()throws Exception{var r=waiting();armed(r);acknowledgedOff(r);when(valveTransport.circuitValveConnected(anyString())).thenReturn(false);closure.poll();assertEquals("UNRESOLVED",saved(r.sessionId()).state());when(valveTransport.circuitValveConnected(anyString())).thenReturn(true);clearInvocations(valveTransport);closure.poll();verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void twoEvaluatorsReserveCloseOnce()throws Exception{var r=waiting();armed(r);acknowledgedOff(r);clearInvocations(valveTransport);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){for(var f:pool.invokeAll(List.<java.util.concurrent.Callable<Void>>of(()->{closure.poll();return null;},()->{closure.poll();return null;})))f.get();}verify(valveTransport,times(1)).publishCircuitValve(anyString(),any());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM circuit_demo_command WHERE action='CLOSE'",Integer.class));}
 @Test void pauseDuringPublishDoesNotFinishOrReplay()throws Exception{var r=waiting();var a=armed(r);acknowledgedOff(r);doAnswer(call->{closure.pause("PR1",r.sessionId(),a.armId());return null;}).when(valveTransport).publishCircuitValve(anyString(),any());closure.poll();assertEquals("PAUSED",saved(r.sessionId()).state());closed(current(r.sessionId()));closure.poll();assertEquals("WAIT_CLOSED",current(r.sessionId()).phase());}
 @Test void missingClosedProofExpiresWithoutSecondClose()throws Exception{var r=waiting();armed(r);acknowledgedOff(r);closure.poll();expire(r.sessionId());clearInvocations(valveTransport);closure.poll();assertEquals("EXPIRED",saved(r.sessionId()).state());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void rebootedValveCannotBeClosedByOldArm()throws Exception{var r=waiting();armed(r);acknowledgedOff(r);jdbc.update("UPDATE circuit_demo_status SET boot_id=? WHERE valve_id='VALVE78'",UUID.randomUUID());clearInvocations(valveTransport);closure.poll();assertEquals("INTERRUPTED",saved(r.sessionId()).state());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void armAndViewAreScopedGetIsReadOnly()throws Exception{var r=waiting();clearInvocations(transport,valveTransport);mvc.perform(get("/api/v1/irrigation-circuits/PR1/session/"+r.sessionId()+"/closure")).andExpect(status().isOk()).andExpect(jsonPath("$.canArm").value(true));mvc.perform(get("/api/v1/irrigation-circuits/PR2/session/"+r.sessionId()+"/closure")).andExpect(status().isNotFound());verify(transport,never()).publishCommand(any());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}

 @Test void delayedCloseIsRejectedIfPauseWinsBeforeCommandCommit()throws Exception{var controlled=spy(org.springframework.test.util.AopTestUtils.<CircuitValveControl>getUltimateTargetObject(valves));var localSession=new IrrigationSession(jdbc,mapper,circuits,controlled,pump,fencing,proof,manager,true,false);localSession.interruptOnStartup();var local=new SessionClosure(jdbc,mapper,localSession,manager,true);var r=waiting();var a=armed(r);acknowledgedOff(r);doAnswer(call->{closure.pause("PR1",r.sessionId(),a.armId());return call.callRealMethod();}).when(controlled).create(anyString(),any(),any());clearInvocations(valveTransport);local.poll();assertEquals("PAUSED",saved(r.sessionId()).state());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM circuit_demo_command WHERE command_id=?",Integer.class,a.closeId()));verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void manualCloseTakesOverAndAutoDoesNotFinish()throws Exception{var r=waiting();armed(r);acknowledgedOff(r);var closedStep=step(r,"CLOSE").session();assertEquals("PAUSED",saved(r.sessionId()).state());closed(closedStep);closure.poll();assertEquals("WAIT_CLOSED",current(r.sessionId()).phase());}
 @Test void restartAfterCloseNeverReplaysOrFinishes()throws Exception{var r=waiting();armed(r);acknowledgedOff(r);closure.poll();var closing=current(r.sessionId());service.interruptOnStartup();closed(closing);clearInvocations(valveTransport);closure.poll();assertEquals("INTERRUPTED",saved(r.sessionId()).state());assertEquals("RECOVERY_REQUIRED",current(r.sessionId()).phase());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}

 @Test void schedulerBeforeApplicationReadyCannotUseRetainedArm()throws Exception{var r=waiting();armed(r);acknowledgedOff(r);var starting=new IrrigationSession(jdbc,mapper,circuits,valves,pump,fencing,proof,manager,true,false);var local=new SessionClosure(jdbc,mapper,starting,manager,true);clearInvocations(valveTransport);local.poll();assertEquals("ARMED",saved(r.sessionId()).state());verify(valveTransport,never()).publishCircuitValve(anyString(),any());starting.interruptOnStartup();local.poll();assertEquals("INTERRUPTED",saved(r.sessionId()).state());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
}
